-- ============================================================
-- 外研社七下 s4 语法灌库(junior_grammar_points/questions)
-- publisher='junior_fltrp' · volume='wy7B' · grade=7 · 6 语法点 / 120 题 · code 均 wy7b- 前缀
-- 幂等:按 (publisher, volume) 先删后插。Aaron service role 跑。
-- ============================================================
BEGIN;

DELETE FROM public.junior_grammar_questions q USING public.junior_grammar_points p
 WHERE q.point_id=p.id AND p.publisher='junior_fltrp' AND p.volume='wy7B';
DELETE FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B';

-- 6 语法点

-- 120 题

-- 断言
DO $$
DECLARE ptn int; qn int; prefix_bad int; polluted int; no_cat int; uneven int;
BEGIN
  SELECT count(*) INTO ptn FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B';
  SELECT count(*) INTO qn FROM public.junior_grammar_questions q JOIN public.junior_grammar_points p ON q.point_id=p.id WHERE p.publisher='junior_fltrp' AND p.volume='wy7B';
  SELECT count(*) INTO prefix_bad FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code NOT LIKE 'wy7b-%';
  SELECT count(*) INTO polluted FROM public.junior_grammar_points WHERE volume='wy7B' AND publisher<>'junior_fltrp';
  SELECT count(*) INTO no_cat FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND category_id IS NULL;
  SELECT count(*) INTO uneven FROM (SELECT p.code FROM public.junior_grammar_points p LEFT JOIN public.junior_grammar_questions q ON q.point_id=p.id WHERE p.publisher='junior_fltrp' AND p.volume='wy7B' GROUP BY p.code HAVING count(q.id)<>20) t;
  IF ptn<>6 THEN RAISE EXCEPTION 'point=% 期望6', ptn; END IF;
  IF qn<>120 THEN RAISE EXCEPTION 'question=% 期望120', qn; END IF;
  IF prefix_bad<>0 THEN RAISE EXCEPTION 'code_prefix_bad=%', prefix_bad; END IF;
  IF polluted<>0 THEN RAISE EXCEPTION 'pep_row_polluted=%', polluted; END IF;
  IF no_cat<>0 THEN RAISE EXCEPTION 'category_id_null=%', no_cat; END IF;
  IF uneven<>0 THEN RAISE EXCEPTION 'points_uneven=%', uneven; END IF;
  RAISE NOTICE 'OK: % 点 / % 题,六断言全过', ptn, qn;
END $$;

COMMIT;