INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u1-simple-past', '一般过去时', 'A1', 7, '一般过去时表示过去发生的动作或状态,常与 yesterday、last week、two days ago、just now 连用。规则动词加 -ed(worked, played, studied, stopped);不规则动词需单独记(go→went, see→saw, have→had, do→did)。be 动词过去式:单数 was、复数/you 用 were。否定:实义动词用 didn''t + 动词原形;be 动词用 wasn''t/weren''t。一般疑问:Did + 主语 + 原形;be 动词把 was/were 提前。', 1, 'wy7B', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u2-indefinite-pronouns', '不定代词', 'A1', 7, '不定代词指不确定的人或物:something/anything/nothing/everything(物),someone/anyone/no one/everyone(人)。肯定句用 some-;否定句和疑问句用 any-;no-(nothing/no one)本身表否定,谓语用肯定形式。everything/everyone/something 等作主语时,谓语用单数。形容词修饰不定代词时放其后(something interesting)。', 2, 'wy7B', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u3-linking-verbs', '系动词', 'A1', 7, '系动词后接形容词(不是副词)作表语,说明主语的性质或状态。常见系动词:be(是),become/get/turn/grow(变得),look(看起来)、sound(听起来)、smell(闻起来)、taste(尝起来)、feel(摸/感觉起来)、seem(似乎)。铁律:感官系动词后用形容词,不用副词(It tastes good,不是 tastes well)。', 3, 'wy7B', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u4-imperatives', '祈使句', 'A1', 7, '祈使句表示命令、请求或建议,省略主语 you,以动词原形开头(Open the door.);be 动词开头用 Be(Be quiet.)。否定用 Don''t + 动词原形(Don''t run.)。Let''s + 动词原形表"让我们"(Let''s go.)。加 please 更礼貌。祈使句 + and/or + 结果:Hurry up, or you''ll be late.(否则);Study hard, and you''ll pass.(那么)。', 4, 'wy7B', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u5-comparatives-superlatives', '比较级和最高级', 'A1', 7, '形容词比较两者用比较级(常 + than),三者及以上用最高级(常 the + 最高级)。规则:短词加 -er/-est(tall→taller→tallest);以 e 结尾加 -r/-st;辅音+y 变 i 加 -er/-est(happy→happier→happiest);重读闭音节双写末辅音(big→bigger→biggest);长词用 more/most(beautiful→more/most beautiful)。不规则:good→better→best,bad→worse→worst,many/much→more→most。', 5, 'wy7B', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7b-u6-as-as', 'as...as 同级比较', 'A1', 7, 'as + 形容词/副词原级 + as 表示两者"一样……"(Tom is as tall as Sam.)。否定 not as/so + 原级 + as 表"不如"(A is not as big as B = A 比 B 小)。注意:as...as 中间用原级,不用比较级。可加倍数:twice as ... as。as many/much ... as 表"和……一样多"。', 6, 'wy7B', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'We ____ football in the park yesterday.', 'plays', 'played', 'playing', 'play', 'B', 'yesterday 表过去,规则动词加 -ed。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'She ____ to school by bus last week.', 'goes', 'going', 'go', 'went', 'D', 'go 的过去式是 went。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'I ____ my homework two hours ago.', 'finished', 'finishing', 'finishes', 'finish', 'A', 'two hours ago 表过去,finish 加 -ed。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'Tom ____ a nice picture last Sunday.', 'draws', 'drawing', 'drew', 'draw', 'C', 'draw 的过去式是 drew。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'They ____ very happy at the party.', 'is', 'were', 'was', 'are', 'B', '复数主语 they 的过去式用 were。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'My father ____ at home yesterday evening.', 'are', 'is', 'were', 'was', 'D', '单数主语的过去式 be 用 was。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'Lucy ____ her grandpa last month.', 'visited', 'visits', 'visiting', 'visit', 'A', 'last month 表过去,visit 加 -ed。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'We ____ a lot of photos on the trip.', 'taking', 'takes', 'took', 'take', 'C', 'take 的过去式是 took。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'I ____ up early this morning.', 'gets', 'getting', 'get', 'got', 'D', 'this morning(已过去)+ get 过去式 got。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'She ____ do her homework last night.', 'wasn''t', 'doesn''t', 'didn''t', 'don''t', 'C', '实义动词过去否定用 didn''t + 原形。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), '____ you happy in the old school?', 'Were', 'Was', 'Did', 'Are', 'A', 'be 动词过去疑问,主语 you 用 Were。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), '____ he go to the zoo yesterday?', 'Is', 'Did', 'Was', 'Does', 'B', '实义动词过去疑问用 Did + 原形。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'My friends ____ not at the meeting.', 'are', 'was', 'were', 'did', 'C', '复数主语过去否定 be 用 were not。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'He didn''t ____ the answer last time.', 'knowing', 'knows', 'knew', 'know', 'D', 'didn''t 后接动词原形。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), '— Did you see the film? — Yes, I ____.', 'saw', 'did', 'do', 'was', 'B', '过去一般疑问的肯定简答用 did。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'There ____ many people in the shop just now.', 'were', 'is', 'was', 'are', 'A', 'many people 复数,过去用 were。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'We ____ a big cake and ____ it together.', 'make; ate', 'make; eat', 'made; eat', 'made; ate', 'D', '两个动词都表过去:make→made,eat→ate。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'Last summer we ____ to the beach, but it ____ and we ____ home early.', 'went; rained; came', 'went; rained; come', 'go; rains; come', 'went; rains; came', 'A', '三个动词都表过去:went/rained/came。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), '— What ____ you ____ last weekend? — I ____ my uncle in Beijing.', 'did; do; visit', 'did; do; visited', 'did; did; visited', 'do; do; visited', 'B', '疑问 did+do 原形;答句 visit 过去式 visited。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u1-simple-past'), 'She ____ ill yesterday, so she ____ not come to class and ____ at home.', 'is; did; stayed', 'was; didn''t; stay', 'was; did; stayed', 'was; did; stay', 'C', 'was ill(be过去)+ did not come + stayed(规则过去)。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'I have ____ to tell you. It''s good news.', 'nothing', 'everything', 'something', 'anything', 'C', '肯定句表"某事"用 something。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Is there ____ in the box? It looks empty.', 'someone', 'anything', 'everything', 'something', 'B', '疑问句用 anything。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'She didn''t say ____ about the plan.', 'anything', 'everything', 'something', 'nothing', 'A', '否定句(didn''t)用 anything。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '____ is ready. We can start now.', 'Anything', 'Nothing', 'Anyone', 'Everything', 'D', '"一切都准备好了",肯定用 Everything。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'There is ____ at the door. Can you see who it is?', 'anyone', 'someone', 'no one', 'everyone', 'B', '肯定陈述某人用 someone。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '____ knows the answer, so please help me.', 'Someone', 'Everyone', 'No one', 'Anyone', 'C', '没人知道→No one(本身否定)。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Would you like ____ to drink?', 'anything', 'everything', 'nothing', 'something', 'D', '表示邀请/请求,疑问句也用 something。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'I looked everywhere, but I found ____.', 'nothing', 'everything', 'anything', 'something', 'A', '"什么也没找到",nothing 本身表否定,谓语用肯定 found。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Is ____ going to the party tonight?', 'everyone', 'no one', 'someone', 'anyone', 'D', '疑问句问"有人吗"用 anyone。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Everyone ____ here now. Let''s begin.', 'is', 'were', 'are', 'be', 'A', 'everyone 作主语,谓语用单数 is。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'There is ____ interesting in today''s newspaper.', 'anything', 'something', 'interesting something', 'nothing interesting', 'B', '形容词 interesting 放在 something 之后。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Nobody ____ the window last night.', 'closes', 'didn''t close', 'closed', 'close', 'C', 'nobody 本身否定,谓语用肯定过去式 closed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '— Did you buy ____? — No, the shop had ____.', 'anything; nothing', 'nothing; nothing', 'something; anything', 'anything; something', 'A', '疑问用 anything;答句"什么也没有"用 nothing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'She wants ____ to help her, but ____ is free today.', 'no one; someone', 'anyone; no one', 'someone; anyone', 'someone; no one', 'D', '肯定"想找个人"someone;"没人有空"no one。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '____ is possible if you try, and ____ can stop you.', 'Everything; anything', 'Nothing; everything', 'Everything; nothing', 'Anything; nothing', 'C', '"一切皆有可能"Everything;"没有什么能阻止"nothing。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Is there ____ new in the book? I want to learn ____ useful.', 'something; anything', 'anything; something', 'anything; anything', 'something; something', 'B', '疑问用 anything new;想学"有用的东西"用 something useful。', 3, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '____ likes him because he is kind to ____.', 'Anyone; anyone', 'Someone; anyone', 'No one; no one', 'Everyone; everyone', 'D', '"人人都喜欢他"Everyone;"对每个人都好"everyone。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'He said ____, just sat there quietly.', 'everything', 'anything', 'nothing', 'something', 'C', '"什么也没说",nothing。', 1, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), 'Do you know ____ about the new teacher?', 'nothing', 'anything', 'everything', 'something', 'B', '疑问句用 anything。', 1, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u2-indefinite-pronouns'), '____ in the class was excited about the trip.', 'Everyone', 'No one', 'Anyone', 'Someone', 'A', '"班里每个人都很兴奋",Everyone(单数谓语 was)。', 1, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The cake ____ delicious. I want more.', 'taste', 'tasting', 'tasted', 'tastes', 'D', 'taste 作系动词,主语单数用 tastes。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'You ____ tired. You should rest.', 'looks', 'looked', 'look', 'looking', 'C', '主语 you,look 作系动词用原形。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The music ____ beautiful.', 'sounded', 'sounds', 'sounding', 'sound', 'B', 'sound 作系动词,主语单数用 sounds。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'These flowers ____ sweet.', 'smell', 'smelled', 'smells', 'smelling', 'A', '复数主语 flowers,用 smell。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'In autumn the leaves ____ yellow.', 'turns', 'turned', 'turn', 'turning', 'C', 'turn"变得",复数主语用 turn。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'She ____ a doctor two years ago.', 'became', 'becomes', 'become', 'becoming', 'A', 'become"成为",过去式 became。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The soup tastes ____.', 'goodly', 'good', 'well', 'best', 'B', '系动词 taste 后接形容词 good,不用副词 well。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'Your idea sounds ____ to me.', 'greatest', 'greater', 'greatly', 'great', 'D', '系动词 sound 后接形容词 great,不用副词 greatly。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'After the rain, the air smelled ____.', 'freshly', 'fresh', 'fresher', 'freshest', 'B', '系动词 smell 后用形容词 fresh。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The baby ____ hungry, so it is crying.', 'feel', 'feels well', 'feeling', 'feels', 'D', 'feel 作系动词,主语单数用 feels + 形容词。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'His face ____ red when everyone looked at him.', 'turn', 'turns', 'turned', 'turning', 'C', 'turn"变红",过去式 turned。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'It ____ cold this morning, so I wore a coat.', 'got', 'getting', 'get', 'gets', 'A', 'get"变冷",过去式 got + 形容词。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The story ____ interesting, and everyone enjoyed it.', 'seeming', 'seems', 'seem', 'seemed', 'D', 'seem"似乎",过去式 seemed + 形容词。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'This coat ____ warm and ____ nice on you.', 'feels; looks', 'feel; look', 'feels; look', 'feel; looks', 'A', '两个系动词,主语单数都加 -s:feels/looks。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The food ____ good and ____ good, so we ate a lot.', 'smelled; tasted well', 'smell; taste', 'smelled; tasted', 'smelled well; tasted well', 'C', '感官系动词后用形容词 good,过去式 smelled/tasted。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The weather ____ warmer, and the trees ____ green.', 'get; become', 'got; became', 'got; became greenly', 'gets; becomes', 'B', 'get/become"变"+ 形容词,过去式 got/became。', 3, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'Everyone ____ happy when they heard the good news.', 'feeling', 'feels', 'feel', 'felt', 'D', 'feel"感到",过去式 felt + 形容词。', 1, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The music ____ loud in the quiet room last night.', 'sounded', 'sound', 'sounding', 'sounds', 'A', 'sound 过去式 sounded + 形容词 loud。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'The milk ____ bad. Don''t drink it.', 'taste', 'tastes', 'tasting', 'tasted', 'B', 'taste 系动词,主语单数 tastes + 形容词 bad。', 1, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u3-linking-verbs'), 'She ____ younger than her real age.', 'looked', 'look', 'looks', 'looking', 'C', 'look 系动词,主语单数 looks + 形容词。', 1, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ the door, please. It''s cold.', 'Closing', 'Close', 'Closed', 'Closes', 'B', '祈使句用动词原形 Close。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ quiet in the library.', 'Being', 'Is', 'Are', 'Be', 'D', 'be 动词祈使句用原形 Be。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ run in the classroom.', 'Don''t', 'Doesn''t', 'Not', 'No', 'A', '否定祈使句用 Don''t + 原形。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ go to the park this afternoon.', 'Lets', 'Let', 'Let''s', 'We', 'C', '"让我们"用 Let''s + 原形。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ your books and read page ten.', 'Opening', 'Opened', 'Opens', 'Open', 'D', '祈使句动词原形 Open。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ late for school again.', 'Doesn''t be', 'Not be', 'Don''t be', 'Don''t', 'C', 'be 动词的否定祈使句用 Don''t be。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), 'Please ____ me with my homework.', 'help', 'helps', 'to help', 'helping', 'A', 'please 后祈使句仍用动词原形 help。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ worry. Everything will be fine.', 'No', 'Don''t', 'Not', 'Doesn''t', 'B', '"别担心",Don''t + 原形。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), 'Hurry up, ____ you''ll miss the bus.', 'or', 'and', 'so', 'but', 'A', '祈使句 + or ="否则"。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), 'Study hard, ____ you will pass the test.', 'because', 'or', 'and', 'but', 'C', '祈使句 + and ="那么(就)"。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ cross the road when the light is red.', 'Doesn''t', 'Isn''t', 'Not', 'Don''t', 'D', '"别过马路",Don''t + 原形。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ careful! The floor is wet.', 'Do', 'Be', 'Being', 'Is', 'B', 'be 动词祈使句 Be careful。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ make noise, please. The baby is sleeping.', 'No', 'Doesn''t', 'Not', 'Don''t', 'D', '否定祈使句 Don''t + 原形。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ your hands before dinner, ____ you may get ill.', 'Washes; or', 'Washing; or', 'Wash; or', 'Wash; and', 'C', '祈使句 Wash 原形;+ or"否则"。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ afraid of mistakes, ____ try your best.', 'Don''t; just', 'Don''t be; just', 'Doesn''t be; just', 'Not be; just', 'B', '否定祈使句 Don''t be;just + 祈使。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ turn off the lights, ____ let''s save some money.', 'Please; and', 'Pleases; and', 'Please turn; and', 'Please; or', 'A', '礼貌祈使 Please turn off;+ and"这样"。', 3, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ your seat and ____ quiet during the film.', 'Takes; be', 'Taking; be', 'Take; is', 'Take; be', 'D', '两个祈使:Take(原形)+ be(be动词原形)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ swim here. The water is deep.', 'Don''t', 'Doesn''t', 'No', 'Not', 'A', '"别游泳",Don''t + 原形。', 1, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ have a rest now.', 'We', 'Let', 'Let''s', 'Lets', 'C', '"我们休息吧",Let''s + 原形。', 1, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u4-imperatives'), '____ your friend, and you will make him happy.', 'Helps', 'Help', 'Helped', 'Helping', 'B', '祈使句 Help 原形;+ and"那么"。', 1, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Tom is ____ than his brother.', 'tall', 'taller', 'tallest', 'more tall', 'B', '两者比较用比较级 taller + than。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'This box is ____ than that one.', 'more big', 'biggest', 'bigger', 'big', 'C', 'big 双写 g 加 -er,two 者比较。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Lily is the ____ girl in her class.', 'happiest', 'happier', 'most happy', 'happy', 'A', '三者以上用最高级,happy→happiest。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'The Yangtze River is ____ than that river.', 'more long', 'longest', 'long', 'longer', 'D', '两者比较 longer + than。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Sam runs ____ than me.', 'faster', 'fast', 'fastest', 'more fast', 'A', '比较两者用 faster + than。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'This is the ____ book in the shop.', 'interestingest', 'most interesting', 'more interesting', 'interesting', 'B', '长词最高级用 most interesting。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Her picture is ____ than mine.', 'beautifuler', 'beautiful', 'more beautiful', 'most beautiful', 'C', '长词比较级用 more beautiful。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Health is ____ than money.', 'most important', 'important', 'importanter', 'more important', 'D', '长词比较级 more important + than。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'My English is ____ than before.', 'best', 'better', 'good', 'gooder', 'B', 'good 的比较级是不规则 better。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Today the weather is ____ than yesterday.', 'worst', 'bad', 'badder', 'worse', 'D', 'bad 的比较级是不规则 worse。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Of all the students, Anna works the ____.', 'hardest', 'harder', 'most hard', 'hard', 'A', '三者以上最高级 hardest。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'This film is ____ than that one, so I like it more.', 'most exciting', 'excitinger', 'more exciting', 'exciting', 'C', '长词比较级 more exciting。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Mount Qomolangma is the ____ mountain in the world.', 'higher', 'highest', 'most high', 'high', 'B', '最高级 the highest。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'She has ____ books than I, and she reads the ____ of us all.', 'many; most', 'most; most', 'more; more', 'more; most', 'D', 'many 比较级 more + than;最高级 the most。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'My room is ____ than yours, but Tom''s room is the ____.', 'cleaner; cleanest', 'cleaner; cleaner', 'cleanest; cleaner', 'clean; cleanest', 'A', '两者 cleaner + than;三者以上 the cleanest。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'This question is ____ than that one, but it is not the ____ in the test.', 'hardest; harder', 'harder; harder', 'harder; hardest', 'hard; hardest', 'C', '两者 harder + than;最高级 the hardest。', 3, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'Winter is ____ than autumn here.', 'coldest', 'colder', 'cold', 'more cold', 'B', '两者比较 colder + than。', 1, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'He is one of the ____ boys in the team.', 'most tall', 'taller', 'tall', 'tallest', 'D', 'one of the + 最高级 tallest。', 1, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'A plane is much ____ than a train.', 'faster', 'fast', 'more fast', 'fastest', 'A', '比较级 faster + than(much 修饰)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u5-comparatives-superlatives'), 'This is the ____ day of my life.', 'goodest', 'better', 'best', 'good', 'C', 'good 最高级不规则 the best。', 1, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'Tom is as ____ as his father.', 'tallest', 'more tall', 'taller', 'tall', 'D', 'as...as 中间用原级 tall。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This book is as ____ as that one.', 'interesting', 'most interesting', 'interestinger', 'more interesting', 'A', 'as...as 用原级 interesting。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'My bag is as ____ as yours.', 'heavier', 'heaviest', 'heavy', 'more heavy', 'C', '同级比较用原级 heavy。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'She sings as ____ as a bird.', 'sweet', 'sweetly', 'sweeter', 'sweetest', 'B', 'as...as 修饰动词 sings 用副词原级 sweetly。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'Today is as ____ as yesterday.', 'warmer', 'warmest', 'more warm', 'warm', 'D', '同级比较 as warm as。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This river is not as ____ as that one.', 'more deep', 'deeper', 'deep', 'deepest', 'C', 'not as...as 中间仍用原级 deep。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'A bike is not as ____ as a car.', 'faster', 'fast', 'more fast', 'fastest', 'B', 'not as fast as ="不如……快"。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'Her hair is as ____ as mine.', 'long', 'more long', 'longest', 'longer', 'A', 'as long as,原级。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This exam is not ____ difficult ____ the last one.', 'so; than', 'as; than', 'as; as', 'more; as', 'C', 'not as ... as 结构。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'He has as ____ books as I do.', 'most', 'more', 'much', 'many', 'D', 'as many + 可数名词 books + as。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'Please come as ____ as you can.', 'soon', 'sooner', 'soonest', 'more soon', 'A', 'as soon as,副词原级。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'My room is not as ____ as hers; hers is bigger.', 'more big', 'big', 'bigger', 'biggest', 'B', 'not as big as ="不如……大"。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This bottle holds ____ as much water as that one.', 'twice more', 'double', 'two', 'twice', 'D', 'twice as much as ="两倍多"。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'My sister is not as ____ as me, but she runs as ____ as I do.', 'taller; faster', 'taller; fast', 'tall; fast', 'tall; faster', 'C', '两处 as...as 都用原级:tall / fast。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This question is as ____ as that one, so neither is ____ than the other.', 'easier; harder', 'easy; harder', 'easier; hard', 'easy; hard', 'B', 'as easy as 用原级;后半用比较级 harder + than。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'He read as ____ books as his friend, but not as ____ as the teacher.', 'many; many', 'many; much', 'much; many', 'much; much', 'A', '可数 books 用 as many as(两处)。', 3, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'Your idea is as ____ as mine.', 'best', 'good', 'better', 'gooder', 'B', 'as good as,原级(good 不变 better)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'The film is not as ____ as the book.', 'most exciting', 'excitinger', 'exciting', 'more exciting', 'C', 'not as exciting as,原级。', 1, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'She works as ____ as everyone else.', 'hard', 'harder', 'more hard', 'hardest', 'A', 'as hard as,副词原级。', 1, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7B' AND code='wy7b-u6-as-as'), 'This street is as ____ as that one.', 'wider', 'widest', 'more wide', 'wide', 'D', 'as wide as,原级。', 1, 20, 'mcq');
